-- Migration number: 0102    Carteles de escaparate: plantillas de SISTEMA (datos)
--
-- Migración de DATOS. SÓLO INSERTA plantillas de cartel de sistema
-- (organization_id NULL, is_system 1, status 'published') en poster_templates.
-- No crea ni altera tablas, no toca ninguna fila existente ni de ninguna
-- agencia. Es reversible por redepliegue (el código lector —el panel de
-- «Carteles de escaparate», Cola 20·3— ya está en producción, así que esta
-- migración de datos va SOLA y es segura: lo único que hace es poblar el
-- catálogo de plantillas de muestra que cualquier agencia ve y puede duplicar).
--
-- Las estructuras usan el mismo documento del editor de bloques
-- (structure_json): sólo bloques text/image/qr (el renderizador pdf-lib aún no
-- dibuja 'shape'; eso es Cola 20·3c). El color 'primary'/'secondary' se vincula
-- dinámicamente al Brand Kit de cada agencia al renderizar, y el negrita usa
-- weight>=600. Los bindings {{asset.*}} / {{tenant.*}} se resuelven contra la
-- propiedad real (obra nueva o 2ª mano) y la marca de la agencia.
--
-- Idempotente: no re-inserta una plantilla de sistema con el mismo nombre si ya
-- existe (p. ej. si la migración se reejecuta).

INSERT INTO poster_templates (organization_id, name, description, category, format_key, is_system, status, structure_json, created_at, updated_at)
